970	func sortEnvelope(env *envelope) {
971		sort.Slice(env.Circuits, func(i, j int) bool {
972			if env.Circuits[i].Name != env.Circuits[j].Name {
973				return env.Circuits[i].Name < env.Circuits[j].Name
974			}
975			return env.Circuits[i].Version < env.Circuits[j].Version
976		})
977		sort.Slice(env.Setups, func(i, j int) bool {
978			if env.Setups[i].Name != env.Setups[j].Name {
979				return env.Setups[i].Name < env.Setups[j].Name
980			}
981			return env.Setups[i].Version < env.Setups[j].Version
982		})
983		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
984		sort.Slice(env.Artifacts, func(i, j int) bool {
985			if env.Artifacts[i].Name != env.Artifacts[j].Name {
986				return env.Artifacts[i].Name < env.Artifacts[j].Name
987			}
988			return env.Artifacts[i].Version < env.Artifacts[j].Version
989		})
990	}
