1123	// validatePersistDefinition re-validates a stored definition against its
1124	// version's declared counts: prime modulus, in-range wires and an exact
1125	// constraint count match.
1126	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1127		parsed, err := definitionFromPersist(*def, public, private)
1128		if err != nil {
1129			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1130		}
1131		if !parsed.compatibleWith(constraints, public, private) {
1132			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1133		}
1134		return nil
1135	}
1136	
1137	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
