package zkcircuit

import ("errors";"strings";"testing")

func injectJobVersionDup(t *testing.T, dir, frag string) {
	t.Helper()
	raw, _ := readDataFile(t, dir)
	str := string(raw)
	start := strings.Index(str, `"id": "jx"`)
	seg := str[start:]
	seg2 := strings.Replace(seg, `"version": 1,`, "\"version\": 1,\n              "+frag+",", 1)
	if seg2 == seg { t.Fatal("replace failed") }
	writeDataFile(t, dir, []byte(str[:start]+seg2))
}

func TestScratchVersionAmbiguity(t *testing.T) {
	cases := []string{
		`"VERSION": 2`,
		`"VERSION": 1`,
		`"Version": 2`,
		`"verſion": 2`,
		`"verſion": 2`,
		`"version": 2`, // escaped 's' canonical
		`"VERSION": 2, "kind": "prove"`,
	}
	for _, frag := range cases {
		t.Run(frag, func(t *testing.T) {
			dir := t.TempDir()
			s, _ := Open(dir)
			readyCircuit(t, s, "c", 1)
			readyCircuit(t, s, "c", 2)
			if _, err := s.SubmitJob(boundProveJob("jx","c",1,"")); err != nil { t.Fatal(err) }
			s.Close()
			injectJobVersionDup(t, dir, frag)
			_, err := Open(dir)
			if !errors.Is(err, ErrDataCorrupt) { t.Fatalf("want corrupt, got %v", err) }
			t.Logf("err: %v", err)
			if !strings.Contains(err.Error(), `"jx"`) || !strings.Contains(err.Error(), "version") {
				t.Fatalf("message must name job jx and version: %v", err)
			}
		})
	}
}

func TestScratchLoneSpellingStillReads(t *testing.T) {
	// Replace canonical with a lone ASCII/long-s spelling and expect value read.
	for _, spelling := range []string{`VERSION`, `Version`, `verſion`} {
		t.Run(spelling, func(t *testing.T) {
			dir := t.TempDir()
			s, _ := Open(dir)
			readyCircuit(t, s, "c", 1)
			if _, err := s.SubmitJob(boundProveJob("jx","c",1,"")); err != nil { t.Fatal(err) }
			s.Close()
			raw, _ := readDataFile(t, dir)
			str := string(raw)
			start := strings.Index(str, `"id": "jx"`)
			seg := str[start:]
			seg2 := strings.Replace(seg, `"version": 1`, "`+`\"`+`"+spelling+"`+`\"`+`: 1", 1)
			_ = seg2
			bad := strings.Replace(str, `"id": "jx",
              "circuit": "c",
              "version": 1,`, "", 1)
			_ = bad
			out := strings.Replace(str, `"version": 1,
              "kind": "prove",
              "attempt": 1
            }
          ]`, "\""+spelling+"\": 1,\n              \"kind\": \"prove\",\n              \"attempt\": 1\n            }\n          ]", 1)
			writeDataFile(t, dir, []byte(out))
			s2, err := Open(dir)
			if err != nil { t.Fatalf("lone %s must read: %v", spelling, err) }
			defer s2.Close()
			j, err := s2.GetJob("jx")
			if err != nil || j.Version != 1 { t.Fatalf("lone %s: j=%+v err=%v", spelling, j, err) }
		})
	}
}
